[INBOX_TYPES.WECOM]: 'i-ri-wechat-fill',
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
[INBOX_TYPES.WECOM]: 'i-ri-wechat-line',
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
import wecomInbox from '@wijaya/wecom_channel/frontend/i18n/wecomInbox.json';
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
...wecomInbox,
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
import CreateWecomInbox from '@wijaya/wecom_channel/frontend/CreateWecomInbox.vue';
import { WECOM_CHANNEL_KEY } from '@wijaya/wecom_channel/frontend/channel/wecomChannel';
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
[WECOM_CHANNEL_KEY]: CreateWecomInbox,
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
import { wecomReadableChannelName } from '@wijaya/wecom_channel/frontend/helpers/wecomInbox';
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
const wecomName = wecomReadableChannelName({
  t,
  channelType: props.channelType,
});
if (wecomName) return wecomName;
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
import { buildWecomChannelCard } from '@wijaya/wecom_channel/frontend/channel/wecomChannel';
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
channels.push(buildWecomChannelCard({ t }));
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
import { watch } from 'vue';
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
if (!globalConfig.value) return [];
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
if (!currentAccount.value?.features) return;
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
watch(() => currentAccount.value?.features, initializeEnabledFeatures);
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
if (this.isAWecomChannel) {
  visibleToAllChannelTabs = [
    ...visibleToAllChannelTabs,
    {
      key: 'configuration',
      name: this.$t('INBOX_MGMT.TABS.CONFIGURATION'),
    },
  ];
}
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
import WecomConfigurationPanel from '@wijaya/wecom_channel/frontend/WecomConfigurationPanel.vue';
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
WecomConfigurationPanel,
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
isAWecomChannel() {
  return this.channelType === INBOX_TYPES.WECOM;
},
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
if (this.isAWecomChannel) return true;
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
import { wecomAllowedFileTypes } from '@wijaya/wecom_channel/frontend/composer/wecomComposer';
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
// WeCom supports image/video/file attachments only; no outbound voice/audio.
if (this.isAWecomChannel) return false;
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
if (!this.isOnPrivateNote && this.isAWecomChannel) {
  return wecomAllowedFileTypes();
}
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
import { wecomFileTypeAllowance } from '@wijaya/wecom_channel/frontend/composer/wecomComposer';
// WIJAYA_CUSTOM_END wecom_channel

// WIJAYA_CUSTOM_START wecom_channel
const wecomAllowance = wecomFileTypeAllowance(file, options);
if (wecomAllowance !== undefined) return wecomAllowance;
// WIJAYA_CUSTOM_END wecom_channel
